    // The example as versions 1 to 6 stored it, read back: what each of their documents' « Today » plan
    // means, in the lower band of INASTI's company contribution they never held, with no fund fee given,
    // and with no partner's income given nor either of the household's statuses, which versions 1 to 7
    // never held, no partner assumed and no dependants, which versions 1 to 8 never held, and its car, had none,
    // held all year, assumed, as versions 1 to 9 counted it, and no IT and phone, which versions 1 to 9 never held. An amount it holds none of is stored as the example's at nothing and read back as none.
    public static readonly RiverInputs SavedExample = new(
        2026,
        new CompanyFigures(Example(120_000m), Example(20_000m)),
        new PlanComposition(Vouchers: false, Allowances: false, Rent: false, Equipment: false, Car: false, Copyright: false, Household: false),
        new VoucherInputs(new Input<int>(0, InputOrigin.None), Nothing, Nothing),
        new AllowanceInputs(Nothing, Nothing, Nothing, Nothing),
        new RentInputs(Nothing, Nothing, Nothing),
        new EquipmentInputs(Count(0), Count(0), Count(0), Default(false), Count(0), Nothing, Nothing, NoneGiven, HeldAllYear, HeldAllYear),
        new CarInputs(
            Nothing, Example(new DateOnly(2026, 1, 1)), Nothing, Default(false), Nothing,
            Default(CarEngine.Electric), new Input<int>(0, InputOrigin.None), Default(false), Example(new DateOnly(2026, 1, 1)), Default(false),
            new Input<int>(0, InputOrigin.None), Default(false), Default(false), NoneGiven, HeldAllYear, HeldAllYear),
        new CopyrightInputs(Nothing, Default(true), Default(true), Default(false), NoneGiven),
        Default(true),
        Default(FinancialYear.FifthOrLater),
        Default(CompanyContributionBand.Lower),
        new AdvancePaymentInputs(Nothing, Nothing, Nothing, Nothing),
        Example(50_000m),
        new MunicipalityChoice(MunicipalRates.IncomeYear2026, null, 0.07m, InputOrigin.Default),
        new TaxPrepaymentInputs(new Input<decimal?>(null, InputOrigin.Derived), new AdvancePaymentInputs(Nothing, Nothing, Nothing, Nothing), Default(false)),
        Nothing,
        Default(WithholdingCategory.VvprbisThirdYearOnwards),
        Nothing,
        Default(ContributionsPaidBy.Director),
        NoneGiven,
        NoneGiven,
        new HouseholdInputs(Nothing, Default(false), Default(false), Default(HouseholdStatus.Alone), NoDependants));

    // No dependant: the counts the example holds none of, and no single parent assumed.
    private static DependantInputs NoDependants => new(Count(0), Count(0), Default(false), Count(0), Count(0));

    // An amount or a rate with no default the user has not given: what the same car would cost privately,
    // what the fund bills, the creative share, the fund's fee.
    public static Input<decimal?> NoneGiven => new(null, InputOrigin.Yours);

    // No day the car is had from or given back on, which versions 1 to 9 never held: held all year, assumed.
    private static Input<DateOnly?> HeldAllYear => new(null, InputOrigin.Default);

    private static Input<decimal> Nothing => new(0m, InputOrigin.None);

    private static Input<int> Count(int value) => new(value, InputOrigin.None);

    // The document of that version.
    public static string Of(int version) => version switch
    {
        1 => Version1,
        2 => Version2,
        3 => Version3,
        4 => Version4,
        5 => Version5,
        6 => Version6,
        7 => Version7,
        8 => Version8,
        9 => Version9,
        10 => Version10,
        _ => throw new ArgumentOutOfRangeException(nameof(version), version, "No document of that version was captured."),
    };

    // What the plans of that version's document mean, in its order: the example, then the user's plan.
    public static IReadOnlyList<RiverInputs> Plans(int version) => [version < 7 ? SavedExample : version < 9 ? SavedExampleOfVersion7 : SavedExampleOfVersion9, version switch
    {
        1 => Version1Plan,
        2 => Version2Plan,
        3 => Version3Plan,
        4 => Version3Plan with { BilledContributions = Yours<decimal?>(900m) },
        5 => Version5Plan,
        6 => Version6Plan,
        7 => Version7Plan,
        8 => Version8Plan,
        9 => Version9Plan,
        10 => Version10Plan,
        _ => throw new ArgumentOutOfRangeException(nameof(version), version, "No document of that version was captured."),
    }];

    // The example as version 7 stores it: its running costs no longer hold INASTI's company contribution.
    private static RiverInputs SavedExampleOfVersion7 => SavedExample with { Company = new CompanyFigures(Example(120_000m), Example(19_590.70m)) };

    // The example as version 9 stored it, with the partner assumed that the build before this one opened on and
    // a plan of that version keeps as saved.
    private static RiverInputs SavedExampleOfVersion9 => SavedExampleOfVersion7 with
    {
        Household = SavedExampleOfVersion7.Household with { Status = Default(HouseholdStatus.MarriedOrLegalCohabitant) },
    };

    private static RiverInputs Version1Plan => SavedExample with
    {
        Company = new CompanyFigures(Yours(150_000m), Yours(30_500.50m)),
        Composition = SavedExample.Composition with { Vouchers = true, Rent = true },
        Vouchers = SavedExample.Vouchers with { MealVoucherDays = Yours(220), EcoVouchers = Yours(250m) },
        Rent = new RentInputs(Yours(1_200m), Yours(0.12m), Yours(1_380m)),
        AdvancePayments = SavedExample.AdvancePayments with { First = Yours(3_000m) },
        DirectorPay = Yours(42_000m),
        TaxPrepayments = SavedExample.TaxPrepayments with { Withheld = Yours<decimal?>(9_000m) },
        Reserve = Yours(10_000m),
        DividendCategory = Yours(WithholdingCategory.Standard),
        ContributionsPaidBy = Yours(ContributionsPaidBy.Company),
    };

    private static RiverInputs Version2Plan => SavedExample with
    {
        Composition = SavedExample.Composition with { Vouchers = true, Car = true },
        Vouchers = SavedExample.Vouchers with { MealVoucherDays = Yours(200) },
        Car = PetrolCar,
        DirectorPay = Yours(42_000m),
    };

    // A royalty given before one could follow the pay is a fixed one.
    private static RiverInputs Version3Plan => SavedExample with
    {
        Composition = SavedExample.Composition with { Copyright = true },
        Copyright = SavedExample.Copyright with
        {
            Royalty = Yours(10_000m), FollowsPay = Yours(false), HoldsAttestation = Yours(true), CreativeShare = Yours<decimal?>(0.6m),
        },
        DirectorPay = Yours(42_000m),
    };

    private static RiverInputs Version5Plan => SavedExample with
    {
        Composition = SavedExample.Composition with { Car = true, Copyright = true },
        Car = PetrolCar with { PersonalContribution = Yours(600m) },
        Copyright = SavedExample.Copyright with { CreativeShare = Yours<decimal?>(0.6m) },
        DirectorPay = Yours(42_000m),
    };

    private static RiverInputs Version6Plan => SavedExample with
    {
        Composition = SavedExample.Composition with { Car = true, Copyright = true },
        Car = PetrolCar with { PersonalContribution = Yours(600m), PrivateCost = Yours<decimal?>(7_200m) },
        Copyright = SavedExample.Copyright with
        {
            Royalty = Yours(5_000m), FollowsPay = Yours(true), HoldsAttestation = Yours(true), CreativeShare = Yours<decimal?>(0.6m),
        },
        DirectorPay = Yours(42_000m),
        Municipality = new MunicipalityChoice(MunicipalRates.IncomeYear2026, Namur, 0.085m, InputOrigin.Derived),
        Reserve = Yours(0m),
        BilledContributions = Yours<decimal?>(900m),
    };

    private static RiverInputs Version7Plan => Version6Plan with { CompanyContributionBand = Yours(CompanyContributionBand.Upper), FundFeeRate = Yours<decimal?>(0.0305m) };

    private static RiverInputs Version8Plan => Version7Plan with
    {
        Composition = Version7Plan.Composition with { Household = true },
        Household = Version7Plan.Household with
        {
            PartnerIncome = Yours(9_500m), BothAged66 = Yours(true), Status = Yours(HouseholdStatus.MarriedOrLegalCohabitant),
        },
    };

    private static RiverInputs Version9Plan => Version8Plan with
    {
        Household = Version8Plan.Household with { Dependants = NoDependants with { Children = Yours(2), ChildrenUnder3 = Yours(1), OtherDependants = Yours(1) } },
    };

    private static RiverInputs Version10Plan => Version9Plan with
    {
        Composition = Version9Plan.Composition with { Equipment = true },
        Car = Version9Plan.Car with { HeldFrom = new Input<DateOnly?>(new DateOnly(2026, 9, 17), InputOrigin.Yours) },
        Equipment = Version9Plan.Equipment with
        {
            Pcs = Yours(1), MobilePhones = Yours(1), Internet = Yours(true), PhoneSubscriptions = Yours(1), YearlyCosts = Yours(1_500m),
            PrivateCost = Yours<decimal?>(300m), ProvidedFrom = Yours<DateOnly?>(new DateOnly(2026, 3, 1)),
        },
    };

    // The user's car in versions 2, 5 and 6: a petrol car of 45,000 at 120 g/km, ordered on 1 February 2025
    // and first registered on 1 March, with 9,000 of yearly costs.
    private static CarInputs PetrolCar => SavedExample.Car with
    {
        CatalogueValue = Yours(45_000m),
        FirstRegistration = Yours(new DateOnly(2025, 3, 1)),
        YearlyCosts = Yours(9_000m),
        Engine = Yours(CarEngine.Petrol),
        Co2 = Yours(120),
        Acquired = Yours(new DateOnly(2025, 2, 1)),
    };

    private static Municipality Namur => MunicipalRates.IncomeYear2026.Municipalities.Single(municipality => municipality.InsCode == 92094);

    private static Input<T> Yours<T>(T value) => new(value, InputOrigin.Yours);

    private static Input<T> Default<T>(T value) => new(value, InputOrigin.Default);

    private static Input<T> Example<T>(T value) => new(value, InputOrigin.Example);
}
